options.getOption:
const data = context.panel.data.series[0];
if (!data || !data.fields || data.fields.length < 1) {
  return { title: { text: 'No data', left: 'center', top: 'center' } };
}

const ivField = data.fields.find(f => f.name === 'iv');
if (!ivField) return { title: { text: 'No IV field', left: 'center', top: 'center' } };

const ivs = ivField.values.filter(v => v != null).map(v => Number(v) * 100);
if (ivs.length === 0) return { title: { text: 'No IV data', left: 'center', top: 'center' } };

// Build 5% buckets
const maxBucket = Math.min(Math.ceil(Math.max(...ivs) / 5) * 5 + 5, 150);
const buckets = [];
const counts = [];
for (let b = 0; b < maxBucket; b += 5) {
  buckets.push(b + '-' + (b + 5) + '%');
  counts.push(ivs.filter(v => v >= b && v < b + 5).length);
}

const sorted = [...ivs].sort((a, b) => a - b);
const median = sorted[Math.floor(sorted.length / 2)];
const mean = ivs.reduce((a, b) => a + b, 0) / ivs.length;

return {
  title: { text: 'IV Distribution (' + ivs.length + ' stocks)', subtext: 'Median: ' + median.toFixed(1) + '% | Mean: ' + mean.toFixed(1) + '%', left: 'center' },
  tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' } },
  grid: { top: 70, bottom: 40, left: 50, right: 20 },
  xAxis: { type: 'category', data: buckets, axisLabel: { rotate: 45, fontSize: 10 } },
  yAxis: { type: 'value', name: 'Stock Count' },
  series: [{
    type: 'bar',
    data: counts,
    itemStyle: {
      color: function(params) {
        const idx = params.dataIndex;
        const pct = idx * 5;
        if (pct < 15) return '#52c41a';
        if (pct < 30) return '#1890ff';
        if (pct < 50) return '#faad14';
        return '#f5222d';
      }
    },
    label: { show: true, position: 'top', fontSize: 9, formatter: function(p) { return p.value > 0 ? p.value : ''; } }
  }],
  markLine: { data: [{ xAxis: median / 5, label: { formatter: 'Median' } }] }
};

const data = context.panel.data.series[0];
if (!data || !data.fields || data.fields.length < 3) {
  return { title: { text: 'No data', left: 'center', top: 'center' } };
}

const tField = data.fields.find(f => f.name === 'ticker');
const vField = data.fields.find(f => f.name === 'volume');
const ivField = data.fields.find(f => f.name === 'iv');

if (!tField || !vField || !ivField) return { title: { text: 'Missing fields' } };

const items = [];
for (let i = 0; i < tField.values.length; i++) {
  const iv = Number(ivField.values[i]) * 100;
  items.push({
    name: tField.values[i] + '\n' + iv.toFixed(0) + '%',
    value: Number(vField.values[i]),
    iv: iv
  });
}

return {
  tooltip: {
    formatter: function(p) {
      return p.name.split('\n')[0] + '<br/>Volume: ' + (p.value / 1e6).toFixed(1) + 'M<br/>IV: ' + p.data.iv.toFixed(1) + '%';
    }
  },
  series: [{
    type: 'treemap',
    data: items,
    leafDepth: 1,
    label: { show: true, fontSize: 10, formatter: '{b}' },
    levels: [{
      itemStyle: { borderColor: '#333', borderWidth: 1, gapWidth: 1 }
    }],
    visualMin: 10,
    visualMax: 80,
    visualDimension: 'iv',
    colorMappingBy: 'value'
  }],
  visualMap: {
    type: 'continuous',
    min: 10,
    max: 80,
    inRange: { color: ['#52c41a', '#a0d911', '#fadb14', '#faad14', '#f5222d'] },
    text: ['High IV', 'Low IV'],
    orient: 'horizontal',
    left: 'center',
    bottom: 5,
    dimension: 'iv'
  }
};

const data = context.panel.data.series[0];
if (!data || !data.fields || data.fields.length < 2) {
  return { title: { text: 'No scan metadata', left: 'center', top: 'center' } };
}

const getVal = (name) => {
  const f = data.fields.find(f => f.name === name);
  return f ? Number(f.values[0]) : 0;
};

const total = getVal('total_tickers');
const withIV = getVal('tickers_with_iv');
const highPre = getVal('high_prefilter_count');
const lowPre = getVal('low_prefilter_count');
const highFinal = getVal('high_final_count');
const lowFinal = getVal('low_final_count');

return {
  title: { text: 'Scan Pipeline', left: 'center' },
  tooltip: { trigger: 'item', formatter: '{b}: {c}' },
  legend: { bottom: 5, data: ['High IV Path', 'Low IV Path'] },
  grid: [{ left: '5%', width: '40%' }, { left: '55%', width: '40%' }],
  series: [
    {
      name: 'High IV Path',
      type: 'funnel',
      left: '5%',
      width: '40%',
      top: 60,
      bottom: 40,
      sort: 'descending',
      label: { show: true, position: 'inside', fontSize: 11 },
      data: [
        { value: total, name: 'Total: ' + total },
        { value: withIV, name: 'With IV: ' + withIV },
        { value: highPre, name: 'High Pre-filter: ' + highPre },
        { value: Math.max(highFinal, 1), name: 'High Final: ' + highFinal }
      ],
      itemStyle: { color: function(p) { return ['#1890ff', '#13c2c2', '#faad14', '#f5222d'][p.dataIndex]; } }
    },
    {
      name: 'Low IV Path',
      type: 'funnel',
      left: '55%',
      width: '40%',
      top: 60,
      bottom: 40,
      sort: 'descending',
      label: { show: true, position: 'inside', fontSize: 11 },
      data: [
        { value: total, name: 'Total: ' + total },
        { value: withIV, name: 'With IV: ' + withIV },
        { value: lowPre, name: 'Low Pre-filter: ' + lowPre },
        { value: Math.max(lowFinal, 1), name: 'Low Final: ' + lowFinal }
      ],
      itemStyle: { color: function(p) { return ['#1890ff', '#13c2c2', '#52c41a', '#237804'][p.dataIndex]; } }
    }
  ]
};
